Disburse Cash Transfer To Beneficiary.code:
// Initiate a single disbursement from your Monnify wallet.
post('/api/v2/disbursements/single', {
  amount: $.data.amount, // in Naira, e.g. 15000
  // Your unique reference; reuse it to check status later.
  reference: $.data.paymentId,
  narration: 'Cash transfer - October 2026 cycle',
  destinationBankCode: $.data.bankCode,
  destinationAccountNumber: $.data.accountNumber,
  currency: 'NGN',
  sourceAccountNumber: $.data.walletAccountNumber, // your Monnify wallet account
});

Reserve Account For Customer.code:
// Reserve a dedicated account number for a customer.
post('/api/v2/bank-transfer/reserved-accounts', {
  // Your unique reference for this reserved account.
  accountReference: $.data.memberId,
  accountName: $.data.fullName,
  currencyCode: 'NGN',
  contractCode: '7059707855', // your Monnify contract code
  customerEmail: $.data.email,
  customerName: $.data.fullName,
});

Get Transfer Status.code:
// Get the status of a single disbursement by its reference.
get('/api/v2/disbursements/single/transactions', {
  query: { reference: $.data.paymentId },
});

Search Disbursements For Reconciliation.code:
// List every disbursement from a source account within a date range.
list('/api/v2/disbursements/search-transactions', {
  sourceAccountNumber: $.data.walletAccountNumber, // your Monnify wallet account
  startDate: new Date('2026-10-01'),
  endDate: Date.now(),
});

Search Collection Transactions.code:
// Search collection transactions, one page at a time.
get('/api/v1/transactions/search', {
  query: { page: 0, size: 50 },
});
